CREATE TYPE user_role AS ENUM ('HEAD_ADMIN','BRANCH_ADMIN','INSTRUCTOR','MEMBER'); CREATE TYPE user_status AS ENUM ('INVITED','ACTIVE','DISABLED'); CREATE TYPE invitation_purpose AS ENUM ('INVITE','PASSWORD_RESET');
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, address varchar(255) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL, phone varchar(30) NOT NULL UNIQUE, password_hash varchar(255), status user_status NOT NULL, default_branch_id uuid REFERENCES branches(id) ON DELETE RESTRICT, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose invitation_purpose NOT NULL, token_hash varchar(255) NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, invalidated_at timestamptz, created_by uuid REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(255) NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX invitations_token_hash_uq ON invitations(token_hash); CREATE INDEX invitations_user_purpose_created_idx ON invitations(user_id,purpose,created_at DESC); CREATE UNIQUE INDEX sessions_token_hash_uq ON sessions(token_hash); CREATE INDEX sessions_user_expires_idx ON sessions(user_id,expires_at);
